package com.dongqh.luckyhub.membership;
import com.dongqh.luckyhub.membership.dto.*;import com.dongqh.luckyhub.membership.enums.MembershipCardType;import com.dongqh.luckyhub.membership.service.MembershipService;import com.dongqh.luckyhub.rbac.entity.SysUser;import com.dongqh.luckyhub.rbac.mapper.SysUserMapper;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest class MembershipConcurrencyTests { @Autowired MembershipService service;@Autowired JdbcTemplate jdbc;@Autowired SysUserMapper users;Long userId,productId;@BeforeEach void setup(){jdbc.update("DELETE FROM membership_grant_record");jdbc.update("DELETE FROM user_membership");jdbc.update("DELETE FROM membership_product");SysUser u=new SysUser();u.setUsername("mc-"+UUID.randomUUID());u.setPassword("x");u.setNickname("并发会员");u.setStatus(1);users.insert(u);userId=u.getId();productId=service.createProduct(new CreateMembershipProductCommand("MC","月卡","MEMBER",MembershipCardType.MONTH,30,100L,9000,0,10000)).id();}@AfterEach void clean(){jdbc.update("DELETE FROM membership_grant_record");jdbc.update("DELETE FROM user_membership");jdbc.update("DELETE FROM membership_product");users.deleteById(userId);}@Test void concurrentDuplicatePurchaseExtendsOnce() throws Exception {var pool=Executors.newFixedThreadPool(10);var gate=new CountDownLatch(1);List<Future<?>> fs=new ArrayList<>();for(int i=0;i<10;i++)fs.add(pool.submit(()->{gate.await();return service.purchase(new PurchaseMembershipCommand("ONE",productId,userId));}));gate.countDown();for(var f:fs)f.get();pool.shutdown();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM membership_grant_record WHERE business_no='ONE'",Integer.class)).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM user_membership WHERE user_id=?",Integer.class,userId)).isOne();}}
